import"./auth.BpBfAzbV.js";import"./bookings.C6wKHWj2.js";import"./inventory.DBANs0HS.js";import"./notifications.B66RbRmS.js";window.ReviewsManager=new class{constructor(){this.reviews=[],this.init()}async init(){try{const i=await fetch("/api/reviews",{credentials:"include"});if(i.ok){const e=await i.json();this.reviews=e.reviews||[]}}catch(i){}}async fetchAll(){return await this.init(),this.reviews}getAll(){return this.reviews}getByBookingId(i){return this.reviews.find(e=>e.bookingId===i)||null}async addReview(i){try{const e=await fetch("/api/reviews",{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify(i)});if(e.ok){const i=await e.json();if(i.review)return this.reviews.push(i.review),i.review}}catch(e){}return null}};